// THE EFFECT DRAW.
//
// uEffect's draw (vtable +0x30, 0x9b75e8) and everything under it -- the per-generator drawable check
// (slot 22, 0xa58590) and the three generator draws (slot 21: Model particles 0xa92710, LiteBillboard
// 0xa785b8, LitePolyline 0xaaec24) -- are lifted from the ROM into lifted-draw.js (generated by
// C:\MHGU-Extract\efx\lift.py) and run on cpu.js. This module supplies what that code calls outside
// itself: routines already translated by hand, the C library, and the renderer. The renderer is the
// engine's model drawing -- 0xc8cf1c (begin a model) and 0xc8d208 (draw one of its meshes) -- which is
// where a viewer takes over, through m.svc.beginModel / m.svc.drawMesh. LiteBillboard and LitePolyline
// do not call out: they build primitive records and vertices into the draw context's list and dynamic
// vertex buffer (0x8a2e58), which a viewer reads back after the draw.
import { registerNative, invoke, clobber } from './cpu.js';
import './lifted-draw.js';
import './bridge.js';                  // matMul, eulerMatrix, the work area and memcpy as natives

// The renderer's view of a call: r0..r3, the first n stack words and the CPU (0xc8d208 also takes s0,
// the reflect scale -- see modeldraw.js). The words are looked at, not read by game code, so they
// bypass the memory hooks the checker uses.
export function stackWords(m, c, n){
  const w = [];
  for (let k = 0; k < n; k++){
    const a = (c.r[13] + 4 * k) >>> 0;
    w.push((m.rawByte(a) | (m.rawByte(a + 1) << 8) | (m.rawByte(a + 2) << 16) | (m.rawByte(a + 3) << 24)) >>> 0);
  }
  return w;
}
// Both return 0 on every path (0xc8cfe0, 0xc8d310).
registerNative(0xc8cf1c, (m, c) => { m.svc.beginModel([c.r[0], c.r[1], c.r[2], c.r[3]], stackWords(m, c, 4), c); clobber(c); c.r[0] = 0; });
registerNative(0xc8d208, (m, c) => { m.svc.drawMesh([c.r[0], c.r[1], c.r[2], c.r[3]], stackWords(m, c, 5), c); clobber(c); c.r[0] = 0; });

// uEffect draw for one view.
export function drawEffect(m, owner, view){ invoke(m, 0x9b75e8, [owner, view]); }
